-- Baseline schema: SQLite translation of reference migrations 1717400000000 … 1717400021000.
-- See docs/schema-differences.md for every difference from PostgreSQL.
--
-- Conventions
--   * STRICT tables; quoted camelCase column names identical to the reference.
--   * ids: TEXT UUIDs generated by the application (seed rows use a v4 SQL expression).
--   * money / numeric(15,2): INTEGER cents.  quantity & daysWorked: INTEGER hundredths.
--   * booleans: INTEGER 0/1.   dates: TEXT YYYY-MM-DD.   timestamps: TEXT ISO-8601 UTC (ms, 'Z').
--   * enums: CHECK constraints.  jsonb: TEXT with json_valid().

-- ── Users & roles (1717400006000, 1717400007000, 1717400008000) ──────────────
CREATE TABLE "roles" (
  "id"          TEXT    NOT NULL PRIMARY KEY,
  "name"        TEXT    NOT NULL UNIQUE,
  "permissions" TEXT    NOT NULL DEFAULT '[]'
                CHECK (json_valid("permissions") AND json_type("permissions") = 'array'),
  "isSystem"    INTEGER NOT NULL DEFAULT 0 CHECK ("isSystem" IN (0, 1)),
  "createdAt"   TEXT    NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  "updatedAt"   TEXT    NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))
) STRICT;

CREATE TABLE "users" (
  "id"                 TEXT    NOT NULL PRIMARY KEY,
  "username"           TEXT    NOT NULL UNIQUE,
  "passwordHash"       TEXT    NOT NULL,
  "twoFactorSecret"    TEXT,
  "isTwoFactorEnabled" INTEGER NOT NULL DEFAULT 0 CHECK ("isTwoFactorEnabled" IN (0, 1)),
  "createdAt"          TEXT    NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  "updatedAt"          TEXT    NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  "roleId"             TEXT    REFERENCES "roles" ("id"),
  "isActive"           INTEGER NOT NULL DEFAULT 1 CHECK ("isActive" IN (0, 1))
) STRICT;
CREATE INDEX "IDX_users_roleId" ON "users" ("roleId");

-- ── Audit (1717400009000) ────────────────────────────────────────────────────
-- userId deliberately has no FK: the log must outlive any user record.
CREATE TABLE "audit_logs" (
  "id"         TEXT    NOT NULL PRIMARY KEY,
  "userId"     TEXT,
  "username"   TEXT,
  "action"     TEXT    NOT NULL,
  "method"     TEXT,
  "path"       TEXT,
  "statusCode" INTEGER,
  "detail"     TEXT,
  "createdAt"  TEXT    NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))
) STRICT;
CREATE INDEX "IDX_audit_logs_createdAt" ON "audit_logs" ("createdAt");
CREATE INDEX "IDX_audit_logs_userId" ON "audit_logs" ("userId");

CREATE TRIGGER "TRG_audit_logs_no_update" BEFORE UPDATE ON "audit_logs"
BEGIN SELECT RAISE(ABORT, 'audit_logs rows are append-only'); END;
CREATE TRIGGER "TRG_audit_logs_no_delete" BEFORE DELETE ON "audit_logs"
BEGIN SELECT RAISE(ABORT, 'audit_logs rows are append-only'); END;

-- ── Settings (1717400012000) ─────────────────────────────────────────────────
CREATE TABLE "settings" (
  "key"       TEXT NOT NULL PRIMARY KEY,
  "value"     TEXT NOT NULL DEFAULT '',
  "updatedAt" TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))
) STRICT;

-- ── Counters (1717400005000) ─────────────────────────────────────────────────
CREATE TABLE "counters" (
  "key"   TEXT    NOT NULL PRIMARY KEY,
  "value" INTEGER NOT NULL DEFAULT 0
) STRICT;

-- ── Chart of accounts (1717400000000) ────────────────────────────────────────
CREATE TABLE "accounts" (
  "id"          TEXT    NOT NULL PRIMARY KEY,
  "code"        TEXT    NOT NULL UNIQUE,
  "name"        TEXT    NOT NULL,
  "type"        TEXT    NOT NULL CHECK ("type" IN ('ASSET', 'LIABILITY', 'EQUITY', 'REVENUE', 'EXPENSE')),
  "subtype"     TEXT,
  "description" TEXT,
  "isActive"    INTEGER NOT NULL DEFAULT 1 CHECK ("isActive" IN (0, 1)),
  "parentId"    TEXT    REFERENCES "accounts" ("id") ON DELETE SET NULL,
  "createdAt"   TEXT    NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  "updatedAt"   TEXT    NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))
) STRICT;
CREATE INDEX "IDX_accounts_parentId" ON "accounts" ("parentId");

-- ── Ledger (1717400001000) ───────────────────────────────────────────────────
CREATE TABLE "journal_entries" (
  "id"           TEXT NOT NULL PRIMARY KEY,
  "entryNumber"  TEXT NOT NULL UNIQUE,
  "date"         TEXT NOT NULL CHECK (date("date") IS "date"),
  "description"  TEXT NOT NULL,
  "reference"    TEXT,
  "sourceType"   TEXT,
  "sourceId"     TEXT,
  "status"       TEXT NOT NULL DEFAULT 'POSTED' CHECK ("status" IN ('POSTED', 'REVERSED')),
  "reversalOfId" TEXT REFERENCES "journal_entries" ("id"),
  "createdAt"    TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  "updatedAt"    TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))
) STRICT;
CREATE INDEX "IDX_journal_entries_date" ON "journal_entries" ("date");
CREATE INDEX "IDX_journal_entries_source" ON "journal_entries" ("sourceType", "sourceId");
CREATE UNIQUE INDEX "UQ_journal_entries_reversalOfId" ON "journal_entries" ("reversalOfId")
  WHERE "reversalOfId" IS NOT NULL;

CREATE TABLE "journal_lines" (
  "id"             TEXT    NOT NULL PRIMARY KEY,
  "journalEntryId" TEXT    NOT NULL REFERENCES "journal_entries" ("id") ON DELETE CASCADE,
  "accountId"      TEXT    NOT NULL REFERENCES "accounts" ("id"),
  "description"    TEXT,
  "debit"          INTEGER NOT NULL DEFAULT 0 CHECK ("debit" >= 0),
  "credit"         INTEGER NOT NULL DEFAULT 0 CHECK ("credit" >= 0)
) STRICT;
CREATE INDEX "IDX_journal_lines_journalEntryId" ON "journal_lines" ("journalEntryId");
CREATE INDEX "IDX_journal_lines_accountId" ON "journal_lines" ("accountId");

-- Posted journal entries are immutable: never deleted, lines never changed, and the only
-- permitted update is status POSTED -> REVERSED (plus updatedAt).
CREATE TRIGGER "TRG_journal_entries_no_delete" BEFORE DELETE ON "journal_entries"
BEGIN SELECT RAISE(ABORT, 'journal entries are immutable and cannot be deleted'); END;

CREATE TRIGGER "TRG_journal_entries_restricted_update" BEFORE UPDATE ON "journal_entries"
WHEN NEW."id" IS NOT OLD."id"
  OR NEW."entryNumber" IS NOT OLD."entryNumber"
  OR NEW."date" IS NOT OLD."date"
  OR NEW."description" IS NOT OLD."description"
  OR NEW."reference" IS NOT OLD."reference"
  OR NEW."sourceType" IS NOT OLD."sourceType"
  OR NEW."sourceId" IS NOT OLD."sourceId"
  OR NEW."reversalOfId" IS NOT OLD."reversalOfId"
  OR NEW."createdAt" IS NOT OLD."createdAt"
  OR NOT (NEW."status" IS OLD."status" OR (OLD."status" = 'POSTED' AND NEW."status" = 'REVERSED'))
BEGIN SELECT RAISE(ABORT, 'journal entries are immutable; only POSTED -> REVERSED is allowed'); END;

CREATE TRIGGER "TRG_journal_lines_no_update" BEFORE UPDATE ON "journal_lines"
BEGIN SELECT RAISE(ABORT, 'journal lines are immutable'); END;
CREATE TRIGGER "TRG_journal_lines_no_delete" BEFORE DELETE ON "journal_lines"
BEGIN SELECT RAISE(ABORT, 'journal lines are immutable'); END;

-- ── Customers & vendors (1717400002000) ──────────────────────────────────────
CREATE TABLE "customers" (
  "id"        TEXT    NOT NULL PRIMARY KEY,
  "name"      TEXT    NOT NULL,
  "email"     TEXT,
  "phone"     TEXT,
  "address"   TEXT,
  "taxId"     TEXT,
  "isActive"  INTEGER NOT NULL DEFAULT 1 CHECK ("isActive" IN (0, 1)),
  "createdAt" TEXT    NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  "updatedAt" TEXT    NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))
) STRICT;

CREATE TABLE "vendors" (
  "id"        TEXT    NOT NULL PRIMARY KEY,
  "name"      TEXT    NOT NULL,
  "email"     TEXT,
  "phone"     TEXT,
  "address"   TEXT,
  "taxId"     TEXT,
  "isActive"  INTEGER NOT NULL DEFAULT 1 CHECK ("isActive" IN (0, 1)),
  "createdAt" TEXT    NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  "updatedAt" TEXT    NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))
) STRICT;

-- ── Invoices & bills (1717400003000, 10000, 13000–17000) ─────────────────────
CREATE TABLE "invoices" (
  "id"             TEXT    NOT NULL PRIMARY KEY,
  "invoiceNumber"  TEXT    NOT NULL UNIQUE,
  "customerId"     TEXT    REFERENCES "customers" ("id"),
  "date"           TEXT    NOT NULL CHECK (date("date") IS "date"),
  "dueDate"        TEXT    CHECK (date("dueDate") IS "dueDate"),
  "status"         TEXT    NOT NULL DEFAULT 'DRAFT' CHECK ("status" IN ('DRAFT', 'POSTED', 'PAID', 'VOID')),
  "notes"          TEXT,
  "totalAmount"    INTEGER NOT NULL DEFAULT 0,
  "journalEntryId" TEXT    REFERENCES "journal_entries" ("id"),
  "createdAt"      TEXT    NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  "updatedAt"      TEXT    NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  "poNumber"       TEXT,
  "billToName"     TEXT,
  "billToAddress"  TEXT,
  "paymentOptions" TEXT,
  "signatoryName"  TEXT,
  "signatoryTitle" TEXT,
  "paymentTerms"   TEXT,
  "amountPaid"     INTEGER NOT NULL DEFAULT 0,
  "createdById"    TEXT    REFERENCES "users" ("id") ON DELETE SET NULL
) STRICT;
CREATE INDEX "IDX_invoices_createdById" ON "invoices" ("createdById");
CREATE INDEX "IDX_invoices_customerId" ON "invoices" ("customerId");
CREATE INDEX "IDX_invoices_date" ON "invoices" ("date");

CREATE TABLE "invoice_lines" (
  "id"          TEXT    NOT NULL PRIMARY KEY,
  "invoiceId"   TEXT    NOT NULL REFERENCES "invoices" ("id") ON DELETE CASCADE,
  "description" TEXT    NOT NULL,
  "quantity"    INTEGER NOT NULL DEFAULT 100,
  "unitPrice"   INTEGER NOT NULL,
  "amount"      INTEGER NOT NULL,
  "accountId"   TEXT    REFERENCES "accounts" ("id")
) STRICT;
CREATE INDEX "IDX_invoice_lines_invoiceId" ON "invoice_lines" ("invoiceId");

CREATE TABLE "bills" (
  "id"             TEXT    NOT NULL PRIMARY KEY,
  "billNumber"     TEXT    NOT NULL UNIQUE,
  "vendorId"       TEXT    NOT NULL REFERENCES "vendors" ("id"),
  "date"           TEXT    NOT NULL CHECK (date("date") IS "date"),
  "dueDate"        TEXT    CHECK (date("dueDate") IS "dueDate"),
  "status"         TEXT    NOT NULL DEFAULT 'DRAFT' CHECK ("status" IN ('DRAFT', 'POSTED', 'PAID', 'VOID')),
  "notes"          TEXT,
  "totalAmount"    INTEGER NOT NULL DEFAULT 0,
  "journalEntryId" TEXT    REFERENCES "journal_entries" ("id"),
  "createdAt"      TEXT    NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  "updatedAt"      TEXT    NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))
) STRICT;
CREATE INDEX "IDX_bills_vendorId" ON "bills" ("vendorId");

CREATE TABLE "bill_lines" (
  "id"          TEXT    NOT NULL PRIMARY KEY,
  "billId"      TEXT    NOT NULL REFERENCES "bills" ("id") ON DELETE CASCADE,
  "description" TEXT    NOT NULL,
  "quantity"    INTEGER NOT NULL DEFAULT 100,
  "unitPrice"   INTEGER NOT NULL,
  "amount"      INTEGER NOT NULL,
  "accountId"   TEXT    NOT NULL REFERENCES "accounts" ("id")
) STRICT;
CREATE INDEX "IDX_bill_lines_billId" ON "bill_lines" ("billId");

-- ── Banking, expenses, payments (1717400004000) ──────────────────────────────
CREATE TABLE "bank_accounts" (
  "id"             TEXT    NOT NULL PRIMARY KEY,
  "name"           TEXT    NOT NULL,
  "bankName"       TEXT,
  "accountNumber"  TEXT,
  "accountId"      TEXT    NOT NULL REFERENCES "accounts" ("id"),
  "currentBalance" INTEGER NOT NULL DEFAULT 0,
  "isActive"       INTEGER NOT NULL DEFAULT 1 CHECK ("isActive" IN (0, 1)),
  "createdAt"      TEXT    NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  "updatedAt"      TEXT    NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))
) STRICT;

CREATE TABLE "expenses" (
  "id"               TEXT    NOT NULL PRIMARY KEY,
  "expenseNumber"    TEXT    NOT NULL UNIQUE,
  "date"             TEXT    NOT NULL CHECK (date("date") IS "date"),
  "description"      TEXT    NOT NULL,
  "amount"           INTEGER NOT NULL,
  "expenseAccountId" TEXT    NOT NULL REFERENCES "accounts" ("id"),
  "paymentAccountId" TEXT    NOT NULL REFERENCES "accounts" ("id"),
  "receiptUrl"       TEXT,
  "status"           TEXT    NOT NULL DEFAULT 'DRAFT' CHECK ("status" IN ('DRAFT', 'POSTED', 'VOID')),
  "journalEntryId"   TEXT    REFERENCES "journal_entries" ("id"),
  "createdAt"        TEXT    NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  "updatedAt"        TEXT    NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))
) STRICT;

CREATE TABLE "payments" (
  "id"               TEXT    NOT NULL PRIMARY KEY,
  "paymentNumber"    TEXT    NOT NULL UNIQUE,
  "type"             TEXT    NOT NULL CHECK ("type" IN ('AR', 'AP')),
  "invoiceId"        TEXT    REFERENCES "invoices" ("id"),
  "billId"           TEXT    REFERENCES "bills" ("id"),
  "customerId"       TEXT    REFERENCES "customers" ("id"),
  "vendorId"         TEXT    REFERENCES "vendors" ("id"),
  "date"             TEXT    NOT NULL CHECK (date("date") IS "date"),
  "amount"           INTEGER NOT NULL,
  "paymentMethod"    TEXT    NOT NULL DEFAULT 'BANK_TRANSFER' CHECK ("paymentMethod" IN ('CASH', 'BANK_TRANSFER', 'CHECK')),
  "paymentAccountId" TEXT    NOT NULL REFERENCES "accounts" ("id"),
  "notes"            TEXT,
  "journalEntryId"   TEXT    REFERENCES "journal_entries" ("id"),
  "createdAt"        TEXT    NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  "updatedAt"        TEXT    NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))
) STRICT;
CREATE INDEX "IDX_payments_invoiceId" ON "payments" ("invoiceId");
CREATE INDEX "IDX_payments_billId" ON "payments" ("billId");

-- ── Employees (1717400018000, 1717400019000, 1717400021000) ──────────────────
CREATE TABLE "employees" (
  "id"               TEXT    NOT NULL PRIMARY KEY,
  "employeeId"       TEXT    NOT NULL,
  "name"             TEXT    NOT NULL,
  "jobTitle"         TEXT,
  "department"       TEXT,
  "email"            TEXT,
  "phone"            TEXT,
  "joinDate"         TEXT    CHECK (date("joinDate") IS "joinDate"),
  "status"           TEXT    NOT NULL DEFAULT 'ACTIVE' CHECK ("status" IN ('ACTIVE', 'ON_LEAVE', 'LEFT')),
  "notes"            TEXT,
  "photoKey"         TEXT,
  "photoMime"        TEXT,
  "userId"           TEXT    REFERENCES "users" ("id") ON DELETE SET NULL,
  "createdAt"        TEXT    NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  "updatedAt"        TEXT    NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  "employmentType"   TEXT    NOT NULL DEFAULT 'PERMANENT' CHECK ("employmentType" IN ('PERMANENT', 'CONTRACT')),
  "epfNumber"        TEXT,
  "nationalId"       TEXT,
  "resignedDate"     TEXT    CHECK (date("resignedDate") IS "resignedDate"),
  "bankName"         TEXT,
  "bankBranch"       TEXT,
  "bankAccountNo"    TEXT,
  "staffLoanBalance" INTEGER NOT NULL DEFAULT 0
) STRICT;
-- Staff numbers are typed by hand; "cen-001" and "CEN-001" must not coexist.
CREATE UNIQUE INDEX "UQ_employees_employeeId_ci" ON "employees" (lower("employeeId"));

CREATE TABLE "employee_documents" (
  "id"             TEXT    NOT NULL PRIMARY KEY,
  "employeeId"     TEXT    NOT NULL REFERENCES "employees" ("id") ON DELETE CASCADE,
  "category"       TEXT    NOT NULL DEFAULT 'OTHER'
                   CHECK ("category" IN ('CERTIFICATE', 'ID', 'CONTRACT', 'VISA', 'OTHER', 'PAYSLIP')),
  "title"          TEXT    NOT NULL,
  "fileKey"        TEXT    NOT NULL,
  "originalName"   TEXT    NOT NULL,
  "mimeType"       TEXT    NOT NULL,
  "size"           INTEGER NOT NULL,
  "expiryDate"     TEXT    CHECK (date("expiryDate") IS "expiryDate"),
  "notes"          TEXT,
  "isCurrent"      INTEGER NOT NULL DEFAULT 1 CHECK ("isCurrent" IN (0, 1)),
  "replacesId"     TEXT    REFERENCES "employee_documents" ("id") ON DELETE SET NULL,
  "uploadedById"   TEXT    REFERENCES "users" ("id") ON DELETE SET NULL,
  "uploadedByName" TEXT,
  "createdAt"      TEXT    NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))
) STRICT;
CREATE INDEX "IDX_employee_documents_employeeId" ON "employee_documents" ("employeeId");

CREATE TABLE "employee_salaries" (
  "id"               TEXT    NOT NULL PRIMARY KEY,
  "employeeId"       TEXT    NOT NULL REFERENCES "employees" ("id") ON DELETE CASCADE,
  "effectiveFrom"    TEXT    NOT NULL CHECK (date("effectiveFrom") IS "effectiveFrom"),
  "basic"            INTEGER NOT NULL DEFAULT 0,
  "bra2005"          INTEGER NOT NULL DEFAULT 0,
  "bra2016"          INTEGER NOT NULL DEFAULT 0,
  "vehicleAllowance" INTEGER NOT NULL DEFAULT 0,
  "otherAllowance"   INTEGER NOT NULL DEFAULT 0,
  "epfApplicable"    INTEGER NOT NULL DEFAULT 1 CHECK ("epfApplicable" IN (0, 1)),
  "welfareDeduction" INTEGER NOT NULL DEFAULT 30000,
  "loanInstallment"  INTEGER NOT NULL DEFAULT 0,
  "reason"           TEXT,
  "notes"            TEXT,
  "createdById"      TEXT    REFERENCES "users" ("id") ON DELETE SET NULL,
  "createdByName"    TEXT,
  "createdAt"        TEXT    NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  "updatedAt"        TEXT    NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  CONSTRAINT "UQ_employee_salaries_employee_date" UNIQUE ("employeeId", "effectiveFrom")
) STRICT;
CREATE INDEX "IDX_employee_salaries_employeeId" ON "employee_salaries" ("employeeId");

-- ── Payroll runs (1717400020000, 1717400021000) ──────────────────────────────
CREATE TABLE "payroll_runs" (
  "id"                    TEXT    NOT NULL PRIMARY KEY,
  "runNumber"             TEXT    NOT NULL UNIQUE,
  "period"                TEXT    NOT NULL CHECK ("period" GLOB '[0-9][0-9][0-9][0-9]-[0-1][0-9]'),
  "periodStart"           TEXT    NOT NULL CHECK (date("periodStart") IS "periodStart"),
  "periodEnd"             TEXT    NOT NULL CHECK (date("periodEnd") IS "periodEnd"),
  "status"                TEXT    NOT NULL DEFAULT 'DRAFT' CHECK ("status" IN ('DRAFT', 'POSTED', 'PAID', 'VOID')),
  "notes"                 TEXT,
  "ratesSnapshot"         TEXT    NOT NULL DEFAULT '{}' CHECK (json_valid("ratesSnapshot")),
  "employeeCount"         INTEGER NOT NULL DEFAULT 0,
  "earningsTotal"         INTEGER NOT NULL DEFAULT 0,
  "noPayTotal"            INTEGER NOT NULL DEFAULT 0,
  "grossTotal"            INTEGER NOT NULL DEFAULT 0,
  "epfEmployeeTotal"      INTEGER NOT NULL DEFAULT 0,
  "payeTotal"             INTEGER NOT NULL DEFAULT 0,
  "stampDutyTotal"        INTEGER NOT NULL DEFAULT 0,
  "welfareTotal"          INTEGER NOT NULL DEFAULT 0,
  "loanRecoveryTotal"     INTEGER NOT NULL DEFAULT 0,
  "salaryAdvanceTotal"    INTEGER NOT NULL DEFAULT 0,
  "otherDeductionsTotal"  INTEGER NOT NULL DEFAULT 0,
  "deductionsTotal"       INTEGER NOT NULL DEFAULT 0,
  "netTotal"              INTEGER NOT NULL DEFAULT 0,
  "epfEmployerTotal"      INTEGER NOT NULL DEFAULT 0,
  "etfTotal"              INTEGER NOT NULL DEFAULT 0,
  "employerWelfareTotal"  INTEGER NOT NULL DEFAULT 0,
  "costToCompanyTotal"    INTEGER NOT NULL DEFAULT 0,
  "journalEntryId"        TEXT    REFERENCES "journal_entries" ("id"),
  "paymentJournalEntryId" TEXT    REFERENCES "journal_entries" ("id"),
  "paymentAccountId"      TEXT    REFERENCES "accounts" ("id"),
  "payDate"               TEXT    CHECK (date("payDate") IS "payDate"),
  "postedAt"              TEXT,
  "paidAt"                TEXT,
  "createdById"           TEXT    REFERENCES "users" ("id") ON DELETE SET NULL,
  "createdByName"         TEXT,
  "createdAt"             TEXT    NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  "updatedAt"             TEXT    NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  "slipsFiledAt"          TEXT
) STRICT;
-- One live run per month; a VOID run may be redone.
CREATE UNIQUE INDEX "UQ_payroll_runs_period_live" ON "payroll_runs" ("period") WHERE "status" <> 'VOID';

CREATE TABLE "payroll_lines" (
  "id"               TEXT    NOT NULL PRIMARY KEY,
  "runId"            TEXT    NOT NULL REFERENCES "payroll_runs" ("id") ON DELETE CASCADE,
  "employeeId"       TEXT    REFERENCES "employees" ("id") ON DELETE SET NULL,
  "salaryId"         TEXT    REFERENCES "employee_salaries" ("id") ON DELETE SET NULL,
  "slipNumber"       TEXT    NOT NULL UNIQUE,
  "employeeCode"     TEXT    NOT NULL,
  "employeeName"     TEXT    NOT NULL,
  "jobTitle"         TEXT,
  "department"       TEXT,
  "employmentType"   TEXT    NOT NULL DEFAULT 'PERMANENT',
  "epfNumber"        TEXT,
  "nationalId"       TEXT,
  "bankName"         TEXT,
  "bankBranch"       TEXT,
  "bankAccountNo"    TEXT,
  "epfApplicable"    INTEGER NOT NULL DEFAULT 1 CHECK ("epfApplicable" IN (0, 1)),
  "daysInMonth"      INTEGER NOT NULL DEFAULT 30,
  "daysWorked"       INTEGER NOT NULL DEFAULT 3000,
  "basic"            INTEGER NOT NULL DEFAULT 0,
  "basicForMonth"    INTEGER NOT NULL DEFAULT 0,
  "bra2005"          INTEGER NOT NULL DEFAULT 0,
  "bra2016"          INTEGER NOT NULL DEFAULT 0,
  "vehicleAllowance" INTEGER NOT NULL DEFAULT 0,
  "otherAllowance"   INTEGER NOT NULL DEFAULT 0,
  "projectBonus"     INTEGER NOT NULL DEFAULT 0,
  "arrears"          INTEGER NOT NULL DEFAULT 0,
  "medical"          INTEGER NOT NULL DEFAULT 0,
  "otherEarnings"    INTEGER NOT NULL DEFAULT 0,
  "earningsTotal"    INTEGER NOT NULL DEFAULT 0,
  "noPayAmount"      INTEGER NOT NULL DEFAULT 0,
  "grossSalary"      INTEGER NOT NULL DEFAULT 0,
  "epfBase"          INTEGER NOT NULL DEFAULT 0,
  "epfEmployee"      INTEGER NOT NULL DEFAULT 0,
  "payeOverride"     INTEGER,
  "paye"             INTEGER NOT NULL DEFAULT 0,
  "stampDuty"        INTEGER NOT NULL DEFAULT 0,
  "welfare"          INTEGER NOT NULL DEFAULT 0,
  "loanRecovery"     INTEGER NOT NULL DEFAULT 0,
  "salaryAdvance"    INTEGER NOT NULL DEFAULT 0,
  "phoneBill"        INTEGER NOT NULL DEFAULT 0,
  "otherDeductions"  INTEGER NOT NULL DEFAULT 0,
  "deductionsTotal"  INTEGER NOT NULL DEFAULT 0,
  "netSalary"        INTEGER NOT NULL DEFAULT 0,
  "epfEmployer"      INTEGER NOT NULL DEFAULT 0,
  "etf"              INTEGER NOT NULL DEFAULT 0,
  "employerWelfare"  INTEGER NOT NULL DEFAULT 0,
  "costToCompany"    INTEGER NOT NULL DEFAULT 0,
  "notes"            TEXT,
  "createdAt"        TEXT    NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  "updatedAt"        TEXT    NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))
) STRICT;
CREATE INDEX "IDX_payroll_lines_runId" ON "payroll_lines" ("runId");
CREATE INDEX "IDX_payroll_lines_employeeId" ON "payroll_lines" ("employeeId");

CREATE TABLE "payroll_remittances" (
  "id"               TEXT    NOT NULL PRIMARY KEY,
  "runId"            TEXT    NOT NULL REFERENCES "payroll_runs" ("id") ON DELETE CASCADE,
  "type"             TEXT    NOT NULL CHECK ("type" IN ('EPF', 'ETF', 'PAYE', 'STAMP_DUTY', 'WELFARE')),
  "amount"           INTEGER NOT NULL,
  "date"             TEXT    NOT NULL CHECK (date("date") IS "date"),
  "paymentAccountId" TEXT    NOT NULL REFERENCES "accounts" ("id"),
  "reference"        TEXT,
  "journalEntryId"   TEXT    REFERENCES "journal_entries" ("id"),
  "createdByName"    TEXT,
  "createdAt"        TEXT    NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))
) STRICT;
CREATE INDEX "IDX_payroll_remittances_runId" ON "payroll_remittances" ("runId");

-- ── Seed data ────────────────────────────────────────────────────────────────
-- Random v4 UUID for seed rows (application code generates its own).
CREATE TEMP VIEW "_uuid" AS SELECT
  lower(hex(randomblob(4))) || '-' || lower(hex(randomblob(2))) || '-4' ||
  substr(lower(hex(randomblob(2))), 2) || '-' ||
  substr('89ab', 1 + (abs(random()) % 4), 1) || substr(lower(hex(randomblob(2))), 2) || '-' ||
  lower(hex(randomblob(6))) AS "v";

-- Roles (1717400007000). Admin holds every key in permissions.ts.
